/**
 * Adds questions to ip-connectivity, ip-services, security-fundamentals, automation.
 * Run: node scripts/expand-questions-2.mjs
 */
import { readFileSync, writeFileSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");
const qDir = join(root, "src", "content", "questions");

function load(file) { return JSON.parse(readFileSync(join(qDir, file), "utf-8")); }
function save(file, data) { writeFileSync(join(qDir, file), JSON.stringify(data, null, 2), "utf-8"); }

// ─── IP CONNECTIVITY (+25 → 50 total) ────────────────────────────────────────
const icExtra = [
  { id:"ic-026",domain:"ip-connectivity",objective:"3.3",difficulty:"easy",text:"Which command adds a default static route on a Cisco router toward a next-hop IP of 203.0.113.1?",options:["A. ip route 0.0.0.0 0.0.0.0 203.0.113.1","B. ip default-route 203.0.113.1","C. ip route default 203.0.113.1","D. ip route 0.0.0.0 255.255.255.255 203.0.113.1"],correct:"A",explanation:"A default static route is configured with network 0.0.0.0 and mask 0.0.0.0, which matches all destinations. It acts as a gateway of last resort.",tags:["static-route","default-route","IPv4"],reference:"Odom CCNA v2 Ch.16" },
  { id:"ic-027",domain:"ip-connectivity",objective:"3.3",difficulty:"medium",text:"What is a floating static route?",options:["A. A route learned via DHCP","B. A static route with a higher administrative distance than the primary dynamic route, used as a backup","C. A default route that changes based on interface status","D. A static route configured without a next-hop"],correct:"B",explanation:"A floating static route has a manually configured AD higher than the dynamic routing protocol (e.g., AD 254 vs OSPF's 110). It only appears in the routing table if the preferred route is lost.",tags:["static-route","floating","AD","backup"],reference:"Odom CCNA v2 Ch.16" },
  { id:"ic-028",domain:"ip-connectivity",objective:"3.3",difficulty:"medium",text:"What is the administrative distance of a static route on Cisco IOS?",options:["A. 0","B. 1","C. 90","D. 110"],correct:"B",explanation:"Static routes have an AD of 1 on Cisco IOS. Connected interfaces have AD 0. EIGRP=90, OSPF=110, RIP=120. Lower AD = more trusted. AD 1 means static routes win over dynamic routes.",tags:["static-route","AD","administrative-distance"],reference:"Odom CCNA v2 Ch.16" },
  { id:"ic-029",domain:"ip-connectivity",objective:"3.4",difficulty:"easy",text:"Which OSPFv2 command advertises the 192.168.1.0/24 network into OSPF area 0?",options:["A. network 192.168.1.0 0.0.0.255 area 0","B. network 192.168.1.0 255.255.255.0 area 0","C. advertise 192.168.1.0/24 area 0","D. ip ospf network 192.168.1.0 area 0"],correct:"A",explanation:"The OSPF network command uses a wildcard mask (inverse of subnet mask). For /24: wildcard = 0.0.0.255. The command enables OSPF on interfaces matching the address/wildcard pattern.",tags:["OSPF","network","wildcard","area0"],reference:"Odom CCNA v2 Ch.20" },
  { id:"ic-030",domain:"ip-connectivity",objective:"3.4",difficulty:"medium",text:"What is the OSPF metric (cost) based on?",options:["A. Hop count","B. Bandwidth","C. Delay","D. MTU"],correct:"B",explanation:"OSPF cost = 100,000,000 / interface bandwidth (bps). A FastEthernet (100 Mbps) link = cost 1, a Serial (1.544 Mbps T1) = cost 64. Lower cost is preferred.",tags:["OSPF","cost","metric","bandwidth"],reference:"Odom CCNA v2 Ch.20" },
  { id:"ic-031",domain:"ip-connectivity",objective:"3.4",difficulty:"medium",text:"In OSPF, which router is elected as Designated Router (DR) on a multi-access network?",options:["A. The router with the highest OSPF cost","B. The router with the highest OSPF priority, then highest router-id","C. The router with the lowest router-id","D. The router with the most interfaces"],correct:"B",explanation:"DR election: highest priority wins (default 1; 0 = ineligible). Ties broken by highest router-id. The router-id is the highest loopback IP or highest active interface IP (if no loopback).",tags:["OSPF","DR","priority","router-id"],reference:"Odom CCNA v2 Ch.20" },
  { id:"ic-032",domain:"ip-connectivity",objective:"3.4",difficulty:"medium",text:"What OSPF neighbor state indicates a full adjacency has been formed between two routers?",options:["A. 2-Way","B. ExStart","C. Full","D. Loading"],correct:"C",explanation:"Full state means the routers have exchanged complete LSDBs. On point-to-point links both become Full with each other; on multi-access only DR/BDR adjacencies reach Full.",tags:["OSPF","neighbor-states","Full","adjacency"],reference:"Odom CCNA v2 Ch.20" },
  { id:"ic-033",domain:"ip-connectivity",objective:"3.4",difficulty:"easy",text:"Which OSPF Hello interval is the default on a FastEthernet interface?",options:["A. 5 seconds","B. 10 seconds","C. 30 seconds","D. 40 seconds"],correct:"B",explanation:"OSPF Hello interval default: 10 seconds on broadcast/point-to-point links; 30 seconds on NBMA links. The Dead interval is 4× Hello by default (40 seconds). Both sides must match for adjacency.",tags:["OSPF","hello","timer"],reference:"Odom CCNA v2 Ch.20" },
  { id:"ic-034",domain:"ip-connectivity",objective:"3.4",difficulty:"hard",text:"What is the purpose of the OSPF passive-interface command?",options:["A. Removes the interface from OSPF completely","B. Prevents OSPF hello packets from being sent out an interface while still advertising the subnet","C. Changes the interface cost to infinite","D. Disables adjacency formation but still sends hellos"],correct:"B",explanation:"passive-interface stops sending/receiving OSPF hellos on the interface (no adjacency forms), but the connected subnet is still advertised into OSPF. Used on interfaces facing end-hosts.",tags:["OSPF","passive-interface","hello"],reference:"Odom CCNA v2 Ch.20" },
  { id:"ic-035",domain:"ip-connectivity",objective:"3.4",difficulty:"medium",text:"What command sets the OSPF router-id to 1.1.1.1 in OSPF process 1?",options:["A. ip ospf router-id 1.1.1.1","B. router-id 1.1.1.1 (under router ospf 1)","C. ospf router-id 1.1.1.1","D. set router-id 1.1.1.1"],correct:"B",explanation:"Under 'router ospf 1' configuration mode, 'router-id 1.1.1.1' sets the OSPF router-id. Requires OSPF process restart ('clear ip ospf process') to take effect if OSPF is already running.",tags:["OSPF","router-id","configuration"],reference:"Odom CCNA v2 Ch.20" },
  { id:"ic-036",domain:"ip-connectivity",objective:"3.5",difficulty:"medium",text:"Which method allows inter-VLAN routing without a Layer 3 switch, using a single physical router interface?",options:["A. Routed ports","B. Router-on-a-stick (802.1Q subinterfaces)","C. SVI per VLAN","D. One physical interface per VLAN"],correct:"B",explanation:"Router-on-a-stick uses 802.1Q subinterfaces on a single physical interface. Each subinterface is assigned an encapsulation and IP address for a VLAN, and the physical link is trunked to the switch.",tags:["inter-VLAN","router-on-a-stick","subinterface","802.1Q"],reference:"Odom CCNA v2 Ch.12" },
  { id:"ic-037",domain:"ip-connectivity",objective:"3.5",difficulty:"medium",text:"On a Layer 3 switch, what must be enabled globally to perform inter-VLAN routing?",options:["A. ip routing","B. ip inter-vlan","C. vlan routing enable","D. switchport routing"],correct:"A",explanation:"'ip routing' enables Layer 3 packet forwarding on a Cisco multilayer switch. Without this command, SVIs have IP addresses but the switch won't route between VLANs.",tags:["inter-VLAN","Layer3-switch","ip-routing","SVI"],reference:"Odom CCNA v2 Ch.12" },
  { id:"ic-038",domain:"ip-connectivity",objective:"3.6",difficulty:"medium",text:"Which FHRP is Cisco-proprietary and uses the concept of Active and Standby routers?",options:["A. VRRP","B. GLBP","C. HSRP","D. IRDP"],correct:"C",explanation:"HSRP (Hot Standby Router Protocol) is Cisco-proprietary. One router is Active (forwards traffic), another is Standby (waits). VRRP is the open-standard equivalent. GLBP is Cisco-proprietary but adds load balancing.",tags:["HSRP","FHRP","active","standby"],reference:"Odom CCNA v2 Ch.18" },
  { id:"ic-039",domain:"ip-connectivity",objective:"3.6",difficulty:"easy",text:"What is the default HSRP group priority?",options:["A. 0","B. 50","C. 100","D. 255"],correct:"C",explanation:"HSRP default priority is 100. Higher priority wins the Active role. If priorities tie, the router with the higher IP address becomes Active.",tags:["HSRP","priority","default"],reference:"Odom CCNA v2 Ch.18" },
  { id:"ic-040",domain:"ip-connectivity",objective:"3.6",difficulty:"medium",text:"In HSRP, when the active router fails and recovers, what must be configured for it to resume the Active role automatically?",options:["A. Preempt","B. Tracking","C. Standby timers","D. Nothing — it automatically resumes"],correct:"A",explanation:"HSRP preempt allows a router that regains the highest priority to take back the Active role. Without preempt, the recovered router remains Standby even if it has higher priority.",tags:["HSRP","preempt","active","failover"],reference:"Odom CCNA v2 Ch.18" },
  { id:"ic-041",domain:"ip-connectivity",objective:"3.4",difficulty:"hard",text:"Which OSPF LSA type is generated by an ASBR to describe routes from external routing domains?",options:["A. Type 1 (Router LSA)","B. Type 2 (Network LSA)","C. Type 5 (AS External LSA)","D. Type 3 (Summary LSA)"],correct:"C",explanation:"Type 5 LSAs are originated by ASBRs and flooded throughout the OSPF domain (except stub areas) to advertise routes from external sources (e.g., redistributed static or BGP routes).",tags:["OSPF","LSA","Type5","ASBR"],reference:"Odom CCNA v2 Ch.21" },
  { id:"ic-042",domain:"ip-connectivity",objective:"3.3",difficulty:"medium",text:"A routing table shows 'S* 0.0.0.0/0 [1/0] via 10.0.0.1'. What does the 'S*' indicate?",options:["A. Static route that is a candidate default gateway","B. Summary static route","C. Secure static route","D. Static route for management traffic"],correct:"A",explanation:"'S' means static route. The asterisk (*) marks it as a candidate default route (gateway of last resort). Cisco IOS installs it as the default route if no more specific match exists.",tags:["static-route","default","routing-table","show-ip-route"],reference:"Odom CCNA v2 Ch.16" },
  { id:"ic-043",domain:"ip-connectivity",objective:"3.4",difficulty:"medium",text:"What command verifies OSPF neighbor relationships on a Cisco router?",options:["A. show ip ospf","B. show ip ospf neighbor","C. show ip route ospf","D. debug ip ospf adj"],correct:"B",explanation:"'show ip ospf neighbor' lists all OSPF neighbors, their states (2-Way, Full, etc.), Dead time, neighbor router-id, and the local interface. It's the first command to verify OSPF operation.",tags:["OSPF","verification","neighbor","show"],reference:"Odom CCNA v2 Ch.20" },
  { id:"ic-044",domain:"ip-connectivity",objective:"3.1",difficulty:"easy",text:"Which command shows all IP interfaces with their IP addresses, line protocol status, and method (DHCP or manual)?",options:["A. show interfaces","B. show ip interface brief","C. show running-config interface","D. show ip address"],correct:"B",explanation:"'show ip interface brief' provides a concise table: interface name, IP address, OK?, method (NVRAM/DHCP/manual), status, and protocol. It's the fastest way to verify interface addressing.",tags:["interface","ip-address","show","verification"],reference:"Odom CCNA v2 Ch.15" },
  { id:"ic-045",domain:"ip-connectivity",objective:"3.3",difficulty:"hard",text:"A static route is configured toward a next-hop address reachable via a dynamic routing protocol. If the dynamic route to the next-hop is lost, what happens to the static route?",options:["A. It stays in the routing table","B. It is removed from the routing table (recursive route lookup fails)","C. It becomes a floating route","D. It switches to the backup interface automatically"],correct:"B",explanation:"IOS uses recursive route lookup for static routes with a next-hop IP. If the route to that next-hop disappears, the static route itself is removed from the routing table (CEF/lookup fails).",tags:["static-route","recursive-lookup","routing-table"],reference:"Odom CCNA v2 Ch.16" },
  { id:"ic-046",domain:"ip-connectivity",objective:"3.4",difficulty:"medium",text:"Which OSPF network type is used by default on Ethernet interfaces?",options:["A. Point-to-point","B. Broadcast","C. Non-broadcast multi-access","D. Point-to-multipoint"],correct:"B",explanation:"Ethernet interfaces default to OSPF broadcast network type, which triggers DR/BDR election. Hello interval is 10s, dead interval is 40s. Point-to-point is used on serial interfaces.",tags:["OSPF","network-type","broadcast","Ethernet"],reference:"Odom CCNA v2 Ch.20" },
  { id:"ic-047",domain:"ip-connectivity",objective:"3.6",difficulty:"hard",text:"Which FHRP supports load balancing by assigning different virtual MAC addresses to multiple routers in the same group?",options:["A. HSRP","B. VRRP","C. GLBP","D. IRDP"],correct:"C",explanation:"GLBP (Gateway Load Balancing Protocol) is Cisco-proprietary and allows up to 4 routers to simultaneously forward traffic for a single virtual IP, using different virtual MAC addresses per router.",tags:["GLBP","FHRP","load-balancing"],reference:"Odom CCNA v2 Ch.18" },
  { id:"ic-048",domain:"ip-connectivity",objective:"3.3",difficulty:"easy",text:"What does 'ip route 10.1.2.0 255.255.255.0 Null0' accomplish?",options:["A. Routes traffic to the next-hop via Null0","B. Discards traffic destined for 10.1.2.0/24 (blackhole route)","C. Creates a default route","D. Redistributes the network into OSPF"],correct:"B",explanation:"A route to Null0 is a blackhole route — all matching traffic is silently dropped. It's used to prevent routing loops with summary routes and to block specific prefixes.",tags:["static-route","null0","blackhole"],reference:"Odom CCNA v2 Ch.16" },
  { id:"ic-049",domain:"ip-connectivity",objective:"3.5",difficulty:"hard",text:"On a Layer 3 switch, which type of interface is a physical port configured with an IP address that does NOT participate in switching?",options:["A. SVI","B. Routed port","C. Access port","D. Trunk port"],correct:"B",explanation:"A routed port ('no switchport' on a physical interface) acts like a router interface — it has an IP address and does Layer 3 forwarding. SVIs are logical interfaces associated with VLANs.",tags:["Layer3-switch","routed-port","no-switchport"],reference:"Odom CCNA v2 Ch.12" },
  { id:"ic-050",domain:"ip-connectivity",objective:"3.4",difficulty:"medium",text:"Two OSPF routers are stuck in the EXSTART/EXCHANGE state. What is the most likely cause?",options:["A. Mismatched hello intervals","B. Mismatched MTU","C. Missing 'network' command","D. Different OSPF process IDs"],correct:"B",explanation:"MTU mismatch is a common cause of EXSTART/EXCHANGE stuck state. OSPF DBD packets with the DF bit set can't traverse links where MTU differs. Use 'ip ospf mtu-ignore' or fix the MTU.",tags:["OSPF","EXSTART","MTU","troubleshooting"],reference:"Odom CCNA v2 Ch.20" },
];

// ─── IP SERVICES (+25 → 50 total) ────────────────────────────────────────────
const isExtra = [
  { id:"is-026",domain:"ip-services",objective:"4.1",difficulty:"easy",text:"What is the primary purpose of NAT (Network Address Translation)?",options:["A. Encrypt packets before forwarding","B. Translate private IPv4 addresses to public addresses for internet access","C. Assign IP addresses to hosts via DHCP","D. Distribute routing information between routers"],correct:"B",explanation:"NAT translates private (RFC 1918) source IP addresses to public addresses so that internal hosts can communicate over the internet without requiring public IPs for each device.",tags:["NAT","private","public","RFC1918"],reference:"Odom CCNA v2 Ch.10" },
  { id:"is-027",domain:"ip-services",objective:"4.1",difficulty:"medium",text:"Which NAT type maps multiple inside hosts to a single public IP using different source port numbers?",options:["A. Static NAT","B. Dynamic NAT","C. PAT (NAT overload)","D. Twice NAT"],correct:"C",explanation:"PAT (Port Address Translation), also called NAT overload, uses a single public IP and unique source port numbers to track sessions for many internal hosts simultaneously.",tags:["PAT","NAT","overload","port"],reference:"Odom CCNA v2 Ch.10" },
  { id:"is-028",domain:"ip-services",objective:"4.1",difficulty:"medium",text:"On a Cisco router, which NAT command identifies the interface connected to the private (internal) network?",options:["A. ip nat inside","B. ip nat outside","C. ip nat pool","D. ip nat enable"],correct:"A",explanation:"'ip nat inside' marks the interface as the private/internal side. 'ip nat outside' marks the public/external side. NAT translates packets flowing between inside and outside interfaces.",tags:["NAT","inside","outside","interface"],reference:"Odom CCNA v2 Ch.10" },
  { id:"is-029",domain:"ip-services",objective:"4.2",difficulty:"easy",text:"What is the default NTP stratum level of a router configured as an NTP master with no external time source?",options:["A. 1","B. 4","C. 8","D. 15"],correct:"C",explanation:"When 'ntp master' is configured without a stratum argument, Cisco IOS defaults to stratum 8. A stratum 1 server is connected to an atomic clock. Lower stratum = more accurate.",tags:["NTP","stratum","master"],reference:"Odom CCNA v2 Ch.8" },
  { id:"is-030",domain:"ip-services",objective:"4.2",difficulty:"medium",text:"Which NTP command configures a router to synchronize its clock to 192.168.1.1?",options:["A. ntp server 192.168.1.1","B. ntp peer 192.168.1.1","C. ntp source 192.168.1.1","D. clock synchronize 192.168.1.1"],correct:"A",explanation:"'ntp server' configures the device as an NTP client that synchronizes to the specified server. 'ntp peer' creates a symmetric peer relationship. 'ntp source' sets the source interface for NTP packets.",tags:["NTP","server","client","synchronize"],reference:"Odom CCNA v2 Ch.8" },
  { id:"is-031",domain:"ip-services",objective:"4.3",difficulty:"easy",text:"Which DHCP message is sent by a client to request an offered IP address from a DHCP server?",options:["A. DHCPDISCOVER","B. DHCPOFFER","C. DHCPREQUEST","D. DHCPACK"],correct:"C",explanation:"DHCP exchange: DISCOVER (client broadcast) → OFFER (server) → REQUEST (client selects offer) → ACK (server confirms). DHCPREQUEST also used for lease renewal.",tags:["DHCP","DORA","REQUEST","lease"],reference:"Odom CCNA v2 Ch.7" },
  { id:"is-032",domain:"ip-services",objective:"4.3",difficulty:"medium",text:"Which Cisco IOS command excludes an IP address from the DHCP pool so it won't be assigned to clients?",options:["A. ip dhcp exclude-address 10.0.0.1","B. no ip dhcp address 10.0.0.1","C. ip dhcp pool exclude 10.0.0.1","D. ip dhcp reserve 10.0.0.1"],correct:"A",explanation:"'ip dhcp excluded-address [start] [end]' prevents those addresses from being assigned. Typically used to reserve the router's IP, other static devices, printers, etc.",tags:["DHCP","excluded-address","IOS"],reference:"Odom CCNA v2 Ch.7" },
  { id:"is-033",domain:"ip-services",objective:"4.3",difficulty:"medium",text:"What is the purpose of 'ip helper-address' on a Cisco router interface?",options:["A. Assigns a secondary IP to an interface","B. Forwards DHCP broadcast requests to a unicast DHCP server on another subnet","C. Restricts DHCP to specific VLANs","D. Enables DHCP snooping on a routed interface"],correct:"B",explanation:"'ip helper-address' converts DHCP broadcasts to unicast and forwards them to the configured DHCP server, enabling clients on remote subnets to use a centralized DHCP server.",tags:["DHCP","helper-address","relay","broadcast"],reference:"Odom CCNA v2 Ch.7" },
  { id:"is-034",domain:"ip-services",objective:"4.4",difficulty:"easy",text:"Which DNS record type maps a hostname to an IPv4 address?",options:["A. AAAA","B. MX","C. CNAME","D. A"],correct:"D",explanation:"An 'A' record (Address record) maps a hostname to an IPv4 address. 'AAAA' maps to IPv6. 'CNAME' is an alias. 'MX' identifies mail servers.",tags:["DNS","A-record","hostname","IPv4"],reference:"Odom CCNA v2 Ch.7" },
  { id:"is-035",domain:"ip-services",objective:"4.4",difficulty:"medium",text:"On a Cisco IOS device, which command configures a DNS server for name resolution?",options:["A. ip name-server 8.8.8.8","B. dns-server 8.8.8.8","C. ip domain-server 8.8.8.8","D. ip dns-resolver 8.8.8.8"],correct:"A",explanation:"'ip name-server [address]' configures up to 6 DNS servers for IOS name resolution. Also requires 'ip domain-lookup' (enabled by default) to perform DNS queries.",tags:["DNS","name-server","IOS","resolution"],reference:"Odom CCNA v2 Ch.7" },
  { id:"is-036",domain:"ip-services",objective:"4.5",difficulty:"medium",text:"What are the three SNMP operations available in SNMPv2c?",options:["A. Get, Set, Trap","B. Get, GetNext, Set","C. Get, GetBulk, Inform","D. Get, Set, Walk"],correct:"A",explanation:"Core SNMP operations: GET (manager reads a variable), SET (manager writes a variable), TRAP (agent sends unsolicited notification). GetNext and GetBulk are also used but the core trio is Get/Set/Trap.",tags:["SNMP","Get","Set","Trap"],reference:"Odom CCNA v2 Ch.8" },
  { id:"is-037",domain:"ip-services",objective:"4.5",difficulty:"medium",text:"Which SNMP version provides encryption and authentication, addressing the plaintext community string weakness of SNMPv1/v2c?",options:["A. SNMPv2u","B. SNMPv3","C. SNMPv2s","D. RMON"],correct:"B",explanation:"SNMPv3 introduced three security levels: noAuthNoPriv, authNoPriv, authPriv. authPriv provides authentication (HMAC-MD5/SHA) and encryption (DES/AES), eliminating plaintext community strings.",tags:["SNMPv3","security","authentication","encryption"],reference:"Odom CCNA v2 Ch.8" },
  { id:"is-038",domain:"ip-services",objective:"4.6",difficulty:"easy",text:"Which syslog severity level number represents 'Critical' conditions?",options:["A. 0","B. 2","C. 4","D. 6"],correct:"B",explanation:"Syslog levels 0-7: 0=Emergency, 1=Alert, 2=Critical, 3=Error, 4=Warning, 5=Notice, 6=Informational, 7=Debug. Remember: 'Every Awful Cisco Engineer Will Need Ice Daily'.",tags:["syslog","severity","critical","logging"],reference:"Odom CCNA v2 Ch.8" },
  { id:"is-039",domain:"ip-services",objective:"4.6",difficulty:"medium",text:"Which IOS command sends syslog messages to a remote server at 10.0.0.5?",options:["A. logging 10.0.0.5","B. syslog server 10.0.0.5","C. logging host 10.0.0.5","D. logging remote 10.0.0.5"],correct:"A",explanation:"'logging [ip-address]' (or 'logging host [ip-address]') sends syslog messages to a remote syslog server. UDP port 514 is used by default.",tags:["syslog","logging","remote","IOS"],reference:"Odom CCNA v2 Ch.8" },
  { id:"is-040",domain:"ip-services",objective:"4.7",difficulty:"medium",text:"Which QoS mechanism classifies and marks traffic at the ingress point, closest to the source?",options:["A. Queuing","B. Traffic policing","C. Classification and marking","D. Congestion avoidance"],correct:"C",explanation:"Classification identifies traffic types; marking (DSCP, CoS) labels them for downstream QoS treatment. Best practice is to classify and mark traffic at the network edge, closest to the source.",tags:["QoS","classification","marking","DSCP"],reference:"Odom CCNA v2 Ch.11" },
  { id:"is-041",domain:"ip-services",objective:"4.7",difficulty:"medium",text:"What does DSCP EF (Expedited Forwarding) represent in QoS?",options:["A. Best-effort traffic","B. Traffic with highest delay/jitter requirements (voice)","C. Network control traffic","D. Bulk data transfers"],correct:"B",explanation:"DSCP EF (DSCP 46) is used for voice/real-time traffic requiring low latency, low jitter, and guaranteed bandwidth. It's the highest-priority forwarding class.",tags:["QoS","DSCP","EF","voice"],reference:"Odom CCNA v2 Ch.11" },
  { id:"is-042",domain:"ip-services",objective:"4.1",difficulty:"hard",text:"A router has 'ip nat inside source list 1 interface Gi0/1 overload'. What does 'overload' mean here?",options:["A. NAT will fail if more than 100 sessions exist","B. Multiple inside hosts share the Gi0/1 IP using PAT (port-based multiplexing)","C. The NAT pool will overflow to a secondary address","D. NAT inspects payload for embedded addresses"],correct:"B",explanation:"'overload' enables PAT — many inside hosts map to the single IP of Gi0/1, differentiated by unique source port numbers. This is the most common home/enterprise internet NAT configuration.",tags:["NAT","PAT","overload","inside-source"],reference:"Odom CCNA v2 Ch.10" },
  { id:"is-043",domain:"ip-services",objective:"4.3",difficulty:"hard",text:"What lease time does Cisco IOS DHCP use by default?",options:["A. 1 hour","B. 12 hours","C. 1 day","D. 8 days"],correct:"C",explanation:"Cisco IOS DHCP default lease is 1 day (24 hours). Configure with 'lease [days] [hours] [minutes]' or 'lease infinite' in the DHCP pool.",tags:["DHCP","lease","default","IOS"],reference:"Odom CCNA v2 Ch.7" },
  { id:"is-044",domain:"ip-services",objective:"4.5",difficulty:"easy",text:"What is the function of an SNMP OID (Object Identifier)?",options:["A. Identify the community string","B. Uniquely identify a managed object in the MIB","C. Authenticate SNMP v3 messages","D. Specify the syslog server address"],correct:"B",explanation:"OIDs are hierarchical numeric identifiers in the MIB (Management Information Base) that uniquely identify each manageable variable (e.g., 1.3.6.1.2.1.1.1 = sysDescr).",tags:["SNMP","OID","MIB","management"],reference:"Odom CCNA v2 Ch.8" },
  { id:"is-045",domain:"ip-services",objective:"4.7",difficulty:"hard",text:"Which QoS scheduling mechanism gives voice traffic strict priority service before all other queues?",options:["A. WFQ","B. CBWFQ","C. LLQ (Low Latency Queuing)","D. FIFO"],correct:"C",explanation:"LLQ (Low Latency Queuing) adds a priority queue to CBWFQ. Traffic in the priority queue (typically voice) is always serviced before other queues, ensuring minimal delay and jitter.",tags:["QoS","LLQ","priority-queue","voice"],reference:"Odom CCNA v2 Ch.11" },
  { id:"is-046",domain:"ip-services",objective:"4.2",difficulty:"hard",text:"Which NTP stratum value indicates an unreachable or unsynchronized clock?",options:["A. 0","B. 8","C. 16","D. 255"],correct:"C",explanation:"NTP stratum 16 means the clock is unsynchronized or unreachable. Stratum 0 is a reference clock (GPS/atomic), stratum 1 is directly connected to stratum 0. Values ≥ 16 are invalid.",tags:["NTP","stratum","unsynchronized"],reference:"Odom CCNA v2 Ch.8" },
  { id:"is-047",domain:"ip-services",objective:"4.4",difficulty:"medium",text:"What is the purpose of a reverse DNS (PTR) record?",options:["A. Maps hostname to IPv6 address","B. Maps an IP address back to a hostname","C. Identifies authoritative name servers","D. Specifies the mail exchange server"],correct:"B",explanation:"A PTR (pointer) record provides reverse DNS — mapping an IP address to a hostname. Used for logging, spam filtering, and network diagnostics. Stored in the in-addr.arpa zone.",tags:["DNS","PTR","reverse-DNS","in-addr.arpa"],reference:"Odom CCNA v2 Ch.7" },
  { id:"is-048",domain:"ip-services",objective:"4.1",difficulty:"medium",text:"What does 'show ip nat translations' display on a Cisco router?",options:["A. All NAT-capable interfaces and their direction","B. Active NAT/PAT mappings showing inside local, inside global, outside local, outside global addresses","C. NAT access control list configuration","D. The NAT pool and remaining addresses"],correct:"B",explanation:"'show ip nat translations' displays the NAT table with four address columns: Inside Local (private source), Inside Global (public source after NAT), Outside Local, Outside Global — showing all active sessions.",tags:["NAT","show","translations","verification"],reference:"Odom CCNA v2 Ch.10" },
  { id:"is-049",domain:"ip-services",objective:"4.6",difficulty:"medium",text:"Which syslog level captures all messages including debug output?",options:["A. Level 4 (Warning)","B. Level 6 (Informational)","C. Level 7 (Debug)","D. Level 0 (Emergency)"],correct:"C",explanation:"Setting logging to level 7 (debug) captures everything — levels 0-7. Production networks should use level 6 or lower; level 7 generates excessive output and can impact performance.",tags:["syslog","debug","level7","logging"],reference:"Odom CCNA v2 Ch.8" },
  { id:"is-050",domain:"ip-services",objective:"4.7",difficulty:"medium",text:"Which field in the IP header is used to set DSCP markings for QoS?",options:["A. TTL","B. Protocol","C. Type of Service (ToS) / DSCP field","D. Fragment Offset"],correct:"C",explanation:"The ToS byte (now called Differentiated Services field) contains the 6-bit DSCP value and 2-bit ECN. DSCP markings allow per-hop behaviors to be applied by routers along the path.",tags:["QoS","DSCP","ToS","IP-header"],reference:"Odom CCNA v2 Ch.11" },
];

// ─── SECURITY FUNDAMENTALS (+25 → 50 total) ──────────────────────────────────
const sfExtra = [
  { id:"sf-026",domain:"security-fundamentals",objective:"5.1",difficulty:"easy",text:"What is the numeric range for standard IPv4 ACLs on Cisco IOS?",options:["A. 1–99 and 1300–1999","B. 100–199 and 2000–2699","C. 1–199","D. 1–50"],correct:"A",explanation:"Standard ACLs use numbers 1–99 and 1300–1999 (extended range). Extended ACLs use 100–199 and 2000–2699. Standard ACLs filter based on source IP only.",tags:["ACL","standard","numbered","range"],reference:"Odom CCNA v2 Ch.3" },
  { id:"sf-027",domain:"security-fundamentals",objective:"5.1",difficulty:"medium",text:"Where should a standard ACL be placed relative to the traffic it is filtering?",options:["A. As close to the source as possible","B. As close to the destination as possible","C. On the core router only","D. On the first router encountered from the internet"],correct:"B",explanation:"Standard ACLs filter only on source IP. Placing them close to the destination minimizes the chance of blocking legitimate traffic from reaching other destinations.",tags:["ACL","standard","placement","best-practice"],reference:"Odom CCNA v2 Ch.3" },
  { id:"sf-028",domain:"security-fundamentals",objective:"5.1",difficulty:"medium",text:"An extended ACL entry reads: 'permit tcp 10.0.0.0 0.0.0.255 any eq 80'. What does this permit?",options:["A. HTTP traffic from the 10.0.0.0/24 subnet to anywhere","B. All TCP traffic from anywhere to 10.0.0.0/24 on port 80","C. All traffic from 10.0.0.0/24","D. HTTPS traffic to the 10.0.0.0/24 subnet"],correct:"A",explanation:"'permit tcp [source] [wildcard] any eq 80' permits TCP traffic from 10.0.0.0/24 going to any destination on destination port 80 (HTTP). 'eq 80' applies to the destination port.",tags:["ACL","extended","TCP","HTTP"],reference:"Odom CCNA v2 Ch.3" },
  { id:"sf-029",domain:"security-fundamentals",objective:"5.1",difficulty:"medium",text:"What wildcard mask matches only the host 192.168.1.100 in an ACL?",options:["A. 0.0.0.255","B. 255.255.255.255","C. 0.0.0.0","D. 255.0.0.0"],correct:"C",explanation:"A wildcard of 0.0.0.0 means all bits must match — this matches exactly one host. The keyword 'host' is equivalent: 'host 192.168.1.100' = '192.168.1.100 0.0.0.0'.",tags:["ACL","wildcard","host","match"],reference:"Odom CCNA v2 Ch.3" },
  { id:"sf-030",domain:"security-fundamentals",objective:"5.1",difficulty:"easy",text:"What implicit rule exists at the end of every Cisco ACL?",options:["A. permit any","B. deny any (implicit deny all)","C. log any","D. No implicit rule — traffic is forwarded by default"],correct:"B",explanation:"Every Cisco ACL ends with an implicit 'deny any' statement. Traffic that doesn't match any explicit permit entry is silently dropped. This is why ACLs must explicitly permit desired traffic.",tags:["ACL","implicit-deny","default"],reference:"Odom CCNA v2 Ch.3" },
  { id:"sf-031",domain:"security-fundamentals",objective:"5.2",difficulty:"easy",text:"Which command encrypts all plaintext passwords in the running configuration?",options:["A. enable password-encryption","B. service password-encryption","C. encrypt all passwords","D. security passwords min-length"],correct:"B",explanation:"'service password-encryption' encrypts passwords using Cisco Type 7 (weak, reversible). It encrypts line passwords, username passwords, and the enable password. The enable secret uses MD5 regardless.",tags:["security","password-encryption","Type7"],reference:"Odom CCNA v2 Ch.1" },
  { id:"sf-032",domain:"security-fundamentals",objective:"5.2",difficulty:"medium",text:"What is the difference between 'enable password' and 'enable secret'?",options:["A. There is no difference","B. enable secret is encrypted with MD5; enable password is plaintext (Type 0) or Type 7","C. enable password is for Telnet; enable secret is for SSH","D. enable secret requires a TACACS+ server"],correct:"B",explanation:"'enable secret' uses MD5 (Type 5) hashing — significantly stronger. 'enable password' uses weak reversible Type 7 or is plaintext. If both are configured, 'enable secret' takes precedence.",tags:["security","enable-secret","enable-password","MD5"],reference:"Odom CCNA v2 Ch.1" },
  { id:"sf-033",domain:"security-fundamentals",objective:"5.3",difficulty:"medium",text:"Which SSH configuration command generates the RSA key pair needed for SSH on a Cisco router?",options:["A. ssh generate key","B. crypto key generate rsa","C. ip ssh rsa key generate","D. crypto rsa key generate modulus"],correct:"B",explanation:"'crypto key generate rsa' generates the RSA key pair. You'll be prompted for modulus size (recommend ≥2048 bits). SSH v2 requires a domain name: 'ip domain-name [name]' must be set first.",tags:["SSH","RSA","crypto","key-generate"],reference:"Odom CCNA v2 Ch.1" },
  { id:"sf-034",domain:"security-fundamentals",objective:"5.3",difficulty:"easy",text:"Which command restricts VTY lines to SSH only (no Telnet)?",options:["A. transport input ssh","B. no transport telnet","C. line vty 0 4 ssh","D. ip ssh only"],correct:"A",explanation:"Under 'line vty 0 4', 'transport input ssh' permits only SSH connections. 'transport input telnet' allows only Telnet. 'transport input all' or 'transport input ssh telnet' allows both.",tags:["SSH","VTY","transport-input","security"],reference:"Odom CCNA v2 Ch.1" },
  { id:"sf-035",domain:"security-fundamentals",objective:"5.4",difficulty:"medium",text:"What is the main difference between RADIUS and TACACS+ for AAA?",options:["A. RADIUS uses TCP; TACACS+ uses UDP","B. TACACS+ encrypts the entire payload and separates auth/authz; RADIUS encrypts only the password","C. RADIUS is Cisco-proprietary; TACACS+ is an IETF standard","D. TACACS+ is only for network access; RADIUS is for device administration"],correct:"B",explanation:"TACACS+ (TCP 49, Cisco-proprietary) encrypts the entire message body and separates Authentication, Authorization, and Accounting. RADIUS (UDP 1812/1813) encrypts only the password field. TACACS+ is preferred for device administration.",tags:["TACACS+","RADIUS","AAA","encryption"],reference:"Odom CCNA v2 Ch.1" },
  { id:"sf-036",domain:"security-fundamentals",objective:"5.7",difficulty:"medium",text:"Which port security violation mode drops the frame, increments the violation counter, but does NOT send a syslog message or shutdown the port?",options:["A. Shutdown","B. Restrict","C. Protect","D. Warning"],correct:"C",explanation:"Port security modes: Protect (drop, no log, no shutdown), Restrict (drop + syslog + increment counter), Shutdown (err-disable port + syslog + SNMP trap). Protect is the least disruptive.",tags:["port-security","protect","violation","Layer2"],reference:"Odom CCNA v2 Ch.4" },
  { id:"sf-037",domain:"security-fundamentals",objective:"5.7",difficulty:"easy",text:"Which command enables port security on a switch interface?",options:["A. security port enable","B. switchport port-security","C. port security maximum 1","D. ip port-security enable"],correct:"B",explanation:"'switchport port-security' enables port security with defaults (max 1 MAC, violation shutdown). The interface must be an access port ('switchport mode access') for port security to work.",tags:["port-security","switchport","configuration"],reference:"Odom CCNA v2 Ch.4" },
  { id:"sf-038",domain:"security-fundamentals",objective:"5.7",difficulty:"medium",text:"What does 'switchport port-security mac-address sticky' do?",options:["A. Manually specifies an allowed MAC address","B. Dynamically learns and stores MAC addresses in the running config","C. Sets the maximum number of MAC addresses","D. Clears the secure MAC table"],correct:"B",explanation:"Sticky learning dynamically learns MAC addresses from connected devices and adds them to the running configuration as secure static entries. Saves the need to manually configure MAC addresses.",tags:["port-security","sticky","dynamic-MAC"],reference:"Odom CCNA v2 Ch.4" },
  { id:"sf-039",domain:"security-fundamentals",objective:"5.5",difficulty:"medium",text:"What does DHCP snooping do?",options:["A. Monitors DHCP traffic to log all IP assignments","B. Blocks DHCP server messages on untrusted ports to prevent rogue DHCP servers","C. Assigns IP addresses based on port security MAC entries","D. Limits the number of DHCP requests per port"],correct:"B",explanation:"DHCP snooping distinguishes trusted ports (uplinks to real DHCP servers) from untrusted ports (access ports). DHCPOFFER/ACK received on untrusted ports are dropped, preventing rogue DHCP attacks.",tags:["DHCP-snooping","security","rogue-DHCP","trusted"],reference:"Odom CCNA v2 Ch.4" },
  { id:"sf-040",domain:"security-fundamentals",objective:"5.5",difficulty:"medium",text:"What Layer 2 attack does Dynamic ARP Inspection (DAI) prevent?",options:["A. VLAN hopping","B. MAC flooding","C. ARP spoofing / ARP poisoning","D. STP manipulation"],correct:"C",explanation:"DAI validates ARP packets against the DHCP snooping binding table. If the IP-to-MAC mapping in an ARP packet doesn't match a trusted entry, it's dropped — preventing ARP poisoning/MitM attacks.",tags:["DAI","ARP-spoofing","Layer2-security","MitM"],reference:"Odom CCNA v2 Ch.4" },
  { id:"sf-041",domain:"security-fundamentals",objective:"5.1",difficulty:"hard",text:"What does the 'established' keyword in an extended ACL entry for TCP do?",options:["A. Allows only new TCP connections","B. Permits TCP segments with ACK or RST bits set (return traffic for established connections)","C. Matches UDP return traffic","D. Establishes a permanent NAT translation"],correct:"B",explanation:"'established' matches TCP segments with ACK=1 or RST=1, which are responses to initiated connections. It's used on inbound interfaces to allow return traffic without permitting new inbound connections.",tags:["ACL","extended","established","TCP","stateless"],reference:"Odom CCNA v2 Ch.3" },
  { id:"sf-042",domain:"security-fundamentals",objective:"5.6",difficulty:"medium",text:"Which 802.1X component acts as the intermediary between the client (supplicant) and the authentication server?",options:["A. Supplicant","B. Authenticator","C. RADIUS server","D. TACACS+ server"],correct:"B",explanation:"802.1X roles: Supplicant (client software), Authenticator (switch/AP — relays EAP), Authentication Server (RADIUS). The switch/authenticator controls port access based on the RADIUS server's decision.",tags:["802.1X","authenticator","supplicant","RADIUS"],reference:"Odom CCNA v2 Ch.4" },
  { id:"sf-043",domain:"security-fundamentals",objective:"5.3",difficulty:"medium",text:"Which IOS command sets the minimum SSH version to version 2?",options:["A. ip ssh version 2","B. ssh version 2","C. crypto ssh version 2","D. transport ssh version 2"],correct:"A",explanation:"'ip ssh version 2' disables SSHv1 and requires SSHv2. SSHv1 has known vulnerabilities. Also configure 'ip ssh time-out' and 'ip ssh authentication-retries' for hardening.",tags:["SSH","version2","security","IOS"],reference:"Odom CCNA v2 Ch.1" },
  { id:"sf-044",domain:"security-fundamentals",objective:"5.2",difficulty:"hard",text:"Which Cisco IOS command creates a local user 'admin' with a privilege level 15 and MD5-hashed password 'C1sco!'?",options:["A. username admin password 15 C1sco!","B. username admin privilege 15 secret C1sco!","C. username admin level 15 enable secret C1sco!","D. create user admin priv 15 pass C1sco!"],correct:"B",explanation:"'username [name] privilege [level] secret [password]' creates a local user with privilege level and MD5-hashed password. 'privilege 15' grants full access. 'secret' hashes with MD5; 'password' does not.",tags:["username","privilege","secret","local-auth"],reference:"Odom CCNA v2 Ch.1" },
  { id:"sf-045",domain:"security-fundamentals",objective:"5.1",difficulty:"medium",text:"Which ACL type filters packets based on both source and destination IP, protocol, and port numbers?",options:["A. Standard ACL","B. Named ACL","C. Extended ACL","D. Dynamic ACL"],correct:"C",explanation:"Extended ACLs can match on source IP, destination IP, protocol (TCP/UDP/ICMP), source port, and destination port — providing granular control. Standard ACLs only match source IP.",tags:["ACL","extended","destination","port"],reference:"Odom CCNA v2 Ch.3" },
  { id:"sf-046",domain:"security-fundamentals",objective:"5.4",difficulty:"hard",text:"What does the 'aaa new-model' command do on a Cisco device?",options:["A. Resets AAA to factory defaults","B. Enables AAA and overrides line-level authentication","C. Creates a new RADIUS server group","D. Forces authentication for console access"],correct:"B",explanation:"'aaa new-model' enables the AAA framework and immediately overrides all line-level authentication (login, password commands). Once enabled, all authentication must be configured through AAA methods.",tags:["AAA","aaa-new-model","authentication","RADIUS"],reference:"Odom CCNA v2 Ch.1" },
  { id:"sf-047",domain:"security-fundamentals",objective:"5.2",difficulty:"easy",text:"Which Cisco banner type is displayed before the login prompt and is legally important for warning unauthorized users?",options:["A. Banner MOTD","B. Banner login","C. Banner exec","D. Banner incoming"],correct:"B",explanation:"Banner login appears before the login prompt and is the legally relevant warning banner for unauthorized access disclaimers. Banner MOTD (Message of the Day) appears before the login banner.",tags:["banner","login","MOTD","security"],reference:"Odom CCNA v2 Ch.1" },
  { id:"sf-048",domain:"security-fundamentals",objective:"5.5",difficulty:"hard",text:"After enabling DHCP snooping on a switch, legitimate DHCP traffic is being blocked on the uplink port to the distribution switch. What is the fix?",options:["A. Disable DHCP snooping globally","B. Enable 'ip dhcp snooping trust' on the uplink interface","C. Add the uplink to a trusted VLAN","D. Configure 'no ip dhcp snooping verify mac-address'"],correct:"B",explanation:"DHCP snooping ports are untrusted by default. Uplinks toward the DHCP server must be explicitly set to trusted: 'ip dhcp snooping trust'. Without this, server responses on the uplink are dropped.",tags:["DHCP-snooping","trusted","uplink","troubleshooting"],reference:"Odom CCNA v2 Ch.4" },
  { id:"sf-049",domain:"security-fundamentals",objective:"5.7",difficulty:"medium",text:"A switch port goes into err-disabled state. Which port security violation mode caused this?",options:["A. Protect","B. Restrict","C. Shutdown","D. Log"],correct:"C",explanation:"The 'shutdown' violation mode (default) disables the port by placing it in err-disabled state when an unauthorized MAC is detected. To recover: 'shutdown' then 'no shutdown' (or configure errdisable recovery).",tags:["port-security","shutdown","err-disabled","violation"],reference:"Odom CCNA v2 Ch.4" },
  { id:"sf-050",domain:"security-fundamentals",objective:"5.1",difficulty:"hard",text:"A named ACL entry is: 'deny ip 172.16.0.0 0.0.255.255 10.0.0.0 0.0.0.255'. What traffic does this deny?",options:["A. All traffic from 172.16.0.0/16 to 10.0.0.0/24","B. All traffic from 10.0.0.0/24 to 172.16.0.0/16","C. ICMP traffic from 172.16.0.0/16","D. All IP traffic from 172.16.0.0/16 to anywhere"],correct:"A",explanation:"'deny ip [source] [wildcard] [destination] [wildcard]' — source is 172.16.0.0/0.0.255.255 (= /16), destination is 10.0.0.0/0.0.0.255 (= /24). Denies all IP from 172.16.x.x to 10.0.0.x.",tags:["ACL","named","wildcard","extended"],reference:"Odom CCNA v2 Ch.3" },
];

// ─── AUTOMATION (+25 → 50 total) ─────────────────────────────────────────────
const auExtra = [
  { id:"au-026",domain:"automation",objective:"6.1",difficulty:"easy",text:"What does REST stand for in the context of network APIs?",options:["A. Reliable Extensible State Transfer","B. Representational State Transfer","C. Remote Execution and State Tunneling","D. Resource Exchange Standard Token"],correct:"B",explanation:"REST (Representational State Transfer) is an architectural style for APIs using HTTP methods (GET, POST, PUT, DELETE). RESTful APIs are stateless and use URLs to identify resources.",tags:["REST","API","HTTP","automation"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-027",domain:"automation",objective:"6.1",difficulty:"medium",text:"Which HTTP method is used to retrieve data from a REST API?",options:["A. POST","B. PUT","C. GET","D. DELETE"],correct:"C",explanation:"GET retrieves resource data (read-only). POST creates a new resource. PUT updates an existing resource. DELETE removes a resource. PATCH partially modifies a resource.",tags:["REST","HTTP","GET","CRUD"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-028",domain:"automation",objective:"6.1",difficulty:"medium",text:"What data format is most commonly used in REST API requests and responses?",options:["A. XML","B. YAML","C. JSON","D. CSV"],correct:"C",explanation:"JSON (JavaScript Object Notation) is the dominant REST API format due to its human-readable syntax, compact size, and native support in most programming languages. XML is also used but less common.",tags:["JSON","REST","API","data-format"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-029",domain:"automation",objective:"6.1",difficulty:"easy",text:"Which JSON structure represents a key-value mapping?",options:["A. An array: [value1, value2]","B. An object: {\"key\": \"value\"}","C. A string: \"key=value\"","D. A tuple: (key, value)"],correct:"B",explanation:"JSON objects use curly braces with key-value pairs: {\"hostname\": \"R1\"}. Arrays use square brackets: [\"Gi0/0\", \"Gi0/1\"]. Keys must be strings.",tags:["JSON","object","key-value","syntax"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-030",domain:"automation",objective:"6.2",difficulty:"medium",text:"In SDN architecture, what is the function of the southbound interface (SBI)?",options:["A. Provides APIs for applications to communicate with the controller","B. Enables the controller to communicate with and program network devices","C. Connects controllers in a multi-controller deployment","D. Provides the GUI for network operators"],correct:"B",explanation:"The SDN southbound interface connects the controller to network devices (data plane). Common SBI protocols: OpenFlow, NETCONF, RESTCONF, gRPC. The northbound interface (NBI) connects to applications.",tags:["SDN","southbound","controller","OpenFlow"],reference:"Odom CCNA v2 Ch.18" },
  { id:"au-031",domain:"automation",objective:"6.2",difficulty:"easy",text:"What is the primary role of an SDN controller?",options:["A. Store configuration backups for all devices","B. Centralize control plane decision-making and program the data plane","C. Provide DHCP and DNS services to network devices","D. Monitor bandwidth utilization only"],correct:"B",explanation:"An SDN controller centralizes the control plane (routing decisions, policies) and uses southbound APIs to program forwarding tables in network devices. Devices become simple packet-forwarding engines.",tags:["SDN","controller","control-plane","data-plane"],reference:"Odom CCNA v2 Ch.18" },
  { id:"au-032",domain:"automation",objective:"6.3",difficulty:"medium",text:"Which configuration management tool is agentless and uses SSH/HTTPS with YAML-based playbooks?",options:["A. Puppet","B. Chef","C. Ansible","D. SaltStack"],correct:"C",explanation:"Ansible is agentless — it connects via SSH or HTTPS without requiring software on managed devices. Playbooks use YAML syntax. Puppet and Chef require agent software on managed nodes.",tags:["Ansible","agentless","YAML","automation"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-033",domain:"automation",objective:"6.3",difficulty:"medium",text:"Which configuration management tool uses a 'master-agent' model with a proprietary DSL?",options:["A. Ansible","B. Puppet","C. Terraform","D. NETCONF"],correct:"B",explanation:"Puppet uses a master-agent model: the Puppet master holds the catalog; agents on managed nodes pull and apply configurations. It uses its own DSL (Puppet language) for manifests.",tags:["Puppet","master-agent","configuration","DSL"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-034",domain:"automation",objective:"6.3",difficulty:"medium",text:"What is the key advantage of configuration management tools over manual CLI configuration?",options:["A. Faster CLI response time","B. Idempotency — applying the same configuration multiple times produces the same result","C. Automatic hardware upgrades","D. Elimination of human operators"],correct:"B",explanation:"Idempotency ensures consistent state — running a playbook/manifest multiple times doesn't create duplicates or errors. This enables automated, repeatable, drift-free configuration.",tags:["idempotency","automation","config-management"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-035",domain:"automation",objective:"6.1",difficulty:"hard",text:"Which protocol uses YANG models and XML encoding to manage network devices over SSH?",options:["A. RESTCONF","B. SNMP","C. NETCONF","D. gRPC"],correct:"C",explanation:"NETCONF (RFC 6241) uses YANG data models, XML encoding, and SSH (TCP 830) for configuration management. It supports transactions with commit/rollback. RESTCONF uses HTTP with JSON/XML.",tags:["NETCONF","YANG","XML","SSH"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-036",domain:"automation",objective:"6.1",difficulty:"medium",text:"What does YANG stand for in network automation?",options:["A. Yet Another Next-generation GUI","B. Yet Another Next-generation data modeling language","C. YANG Automation Node Group","D. Your Automated Network Generator"],correct:"B",explanation:"YANG (Yet Another Next Generation, RFC 6020) is a data modeling language used with NETCONF and RESTCONF. It defines the structure and constraints of configuration and operational data.",tags:["YANG","data-model","NETCONF","RFC6020"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-037",domain:"automation",objective:"6.2",difficulty:"medium",text:"Cisco DNA Center is an example of which type of SDN controller?",options:["A. Open SDN controller","B. NFV orchestrator","C. Intent-based networking controller for enterprise campus/branch","D. Cloud-only WAN controller"],correct:"C",explanation:"Cisco DNA Center (now Cisco Catalyst Center) is Cisco's intent-based networking platform for enterprise campus and branch. It uses RESTCONF/gRPC to manage Catalyst devices and provides analytics.",tags:["Cisco-DNA-Center","SDN","intent-based","enterprise"],reference:"Odom CCNA v2 Ch.18" },
  { id:"au-038",domain:"automation",objective:"6.1",difficulty:"medium",text:"Which HTTP status code indicates a successful REST API request that returned data?",options:["A. 200 OK","B. 201 Created","C. 404 Not Found","D. 500 Internal Server Error"],correct:"A",explanation:"200 OK is returned for successful GET requests. 201 Created is returned after a successful POST. 400 is Bad Request, 401 is Unauthorized, 404 is Not Found, 500 is server error.",tags:["REST","HTTP","status-code","200"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-039",domain:"automation",objective:"6.3",difficulty:"hard",text:"What is the difference between an Ansible playbook and an Ansible role?",options:["A. Playbooks are for Linux; roles are for network devices","B. A playbook is a YAML file defining tasks; a role is a reusable, structured collection of tasks/variables/handlers","C. Roles require an Ansible Tower license","D. Playbooks run once; roles run continuously"],correct:"B",explanation:"An Ansible playbook is a YAML file with plays and tasks. A role is a standardized directory structure (tasks/, vars/, handlers/, templates/) that packages related automation for reuse.",tags:["Ansible","playbook","role","reusability"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-040",domain:"automation",objective:"6.2",difficulty:"medium",text:"What is an API northbound interface (NBI) in SDN used for?",options:["A. Programming the forwarding tables in switches","B. Connecting the SDN controller to network applications and orchestration systems","C. Collecting telemetry from network devices","D. Establishing tunnels between network segments"],correct:"B",explanation:"The northbound interface allows applications (OSS/BSS, orchestrators, analytics platforms) to interact with the SDN controller via REST APIs. Applications express intent; the controller translates to device configurations.",tags:["SDN","northbound","NBI","API"],reference:"Odom CCNA v2 Ch.18" },
  { id:"au-041",domain:"automation",objective:"6.1",difficulty:"easy",text:"What is the purpose of version control (e.g., Git) in network automation?",options:["A. Monitor network device uptime","B. Track changes to configuration files and automation scripts over time","C. Distribute configurations via TFTP","D. Authenticate API requests to network controllers"],correct:"B",explanation:"Version control systems like Git track changes to configuration templates, playbooks, and scripts. This enables rollback, collaboration, change auditing, and CI/CD pipelines for network changes.",tags:["git","version-control","automation","IaC"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-042",domain:"automation",objective:"6.3",difficulty:"medium",text:"What is Infrastructure as Code (IaC)?",options:["A. Using Python scripts to monitor devices","B. Managing and provisioning infrastructure through machine-readable definition files","C. Converting network diagrams to configurations automatically","D. Storing device configurations in SNMP MIBs"],correct:"B",explanation:"IaC treats infrastructure configuration like software code — stored in version control, peer-reviewed, tested, and deployed automatically. Tools: Ansible, Terraform, Puppet, Chef.",tags:["IaC","infrastructure-as-code","automation"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-043",domain:"automation",objective:"6.1",difficulty:"medium",text:"Which RESTCONF operation creates or replaces a resource at a specific URI?",options:["A. GET","B. POST","C. PUT","D. PATCH"],correct:"C",explanation:"In RESTCONF: GET retrieves, POST creates a subordinate, PUT creates or replaces a complete resource, PATCH partially modifies, DELETE removes. RESTCONF runs over HTTP/HTTPS with JSON or XML.",tags:["RESTCONF","PUT","HTTP","operations"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-044",domain:"automation",objective:"6.2",difficulty:"hard",text:"Which type of SDN architecture has each device run its own control plane, but a controller augments decisions without full centralization?",options:["A. Centralized SDN","B. Hybrid SDN","C. Pure OpenFlow SDN","D. Reactive SDN"],correct:"B",explanation:"Hybrid SDN keeps distributed control planes on devices for basic operation while a controller provides overlay policies, analytics, or automation. This eases migration from traditional networking.",tags:["SDN","hybrid","control-plane","architecture"],reference:"Odom CCNA v2 Ch.18" },
  { id:"au-045",domain:"automation",objective:"6.1",difficulty:"easy",text:"What is a Python dictionary equivalent to in JSON?",options:["A. A JSON array","B. A JSON object","C. A JSON string","D. A JSON number"],correct:"B",explanation:"A Python dict {\"key\": value} maps directly to a JSON object {\"key\": value}. A Python list maps to a JSON array. Python's json module converts between them with json.loads() and json.dumps().",tags:["Python","JSON","dictionary","mapping"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-046",domain:"automation",objective:"6.3",difficulty:"medium",text:"What does the 'idempotent' property mean for a NETCONF edit-config operation?",options:["A. The operation is encrypted with AES","B. Running the same configuration multiple times produces the same end state without errors","C. The operation requires admin approval","D. Changes take effect only at the next device reload"],correct:"B",explanation:"Idempotency in NETCONF means applying the same configuration again doesn't create duplicate entries or throw errors. This is essential for automation where playbooks may run repeatedly.",tags:["NETCONF","idempotency","automation","config"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-047",domain:"automation",objective:"6.2",difficulty:"medium",text:"What is the purpose of OpenFlow in SDN?",options:["A. Provide a REST API between applications and the controller","B. Define the protocol for a centralized controller to program flow tables in switches","C. Enable encrypted control-plane communication","D. Replace BGP in data center fabrics"],correct:"B",explanation:"OpenFlow is a southbound protocol that allows an SDN controller to add, modify, and delete flow entries in the flow tables of OpenFlow-enabled switches, separating the control and data planes.",tags:["OpenFlow","SDN","southbound","flow-table"],reference:"Odom CCNA v2 Ch.18" },
  { id:"au-048",domain:"automation",objective:"6.1",difficulty:"hard",text:"Which encoding format does NETCONF use for its messages?",options:["A. JSON","B. CSV","C. XML","D. YAML"],correct:"C",explanation:"NETCONF uses XML encoding for its RPC messages (get, get-config, edit-config, etc.) over SSH (port 830). RESTCONF, by contrast, supports both JSON and XML over HTTP/HTTPS.",tags:["NETCONF","XML","encoding","RFC6241"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-049",domain:"automation",objective:"6.3",difficulty:"easy",text:"Which configuration management tool from HashiCorp focuses on provisioning infrastructure rather than configuration management?",options:["A. Ansible","B. Puppet","C. Terraform","D. Chef"],correct:"C",explanation:"Terraform is an IaC tool for provisioning infrastructure (VMs, cloud resources, networks) using declarative HCL files. Ansible/Puppet/Chef focus on configuring existing systems.",tags:["Terraform","IaC","provisioning","HashiCorp"],reference:"Odom CCNA v2 Ch.19" },
  { id:"au-050",domain:"automation",objective:"6.2",difficulty:"medium",text:"What does Cisco SD-WAN (formerly Viptela) use as its centralized management component?",options:["A. Cisco APIC","B. Cisco DNA Center","C. vManage","D. OpenDaylight"],correct:"C",explanation:"Cisco SD-WAN's architecture: vManage (management NBI), vSmart (control plane/policies), vBond (orchestrator/ZTP), and vEdge/cEdge (data plane WAN routers). vManage provides centralized GUI and REST API.",tags:["SD-WAN","vManage","Cisco","WAN"],reference:"Odom CCNA v2 Ch.18" },
];

